#!/usr/bin/env node
import { Command } from 'commander';
import { addCommand } from './commands/add';
import { initCommand } from './commands/init';
import { listCommand } from './commands/list';
import { pullCommand } from './commands/pull';
import { statusCommand } from './commands/status';
import { upgradeCommand } from './commands/upgrade';
import { requireManifest, saveManifest } from './config';

const program = new Command();

program
  .name('dfiles')
  .description('Manage specific files/folders from multiple git repositories')
  .version('1.0.0');

// init command
program
  .command('init')
  .description('Initialize a new dfiles manifest in a directory')
  .argument('[directory]', 'target directory (default: current directory)')
  .action(async (directory: string | undefined) => {
    await initCommand(directory);
  });

// add command
program
  .command('add')
  .description('Track a file or directory from a remote git repository')
  .argument('<repo>', 'git remote URL (https:// or git@)')
  .argument('<source>', 'path within the repository to track')
  .argument('<destination>', 'local destination path (supports ~)')
  .option('-b, --branch <branch>', 'git branch to use', 'main')
  .option('--id <id>', 'custom entry identifier')
  .action(
    async (
      repo: string,
      source: string,
      destination: string,
      options: { branch: string; id?: string },
    ) => {
      await addCommand(repo, source, destination, options);
    },
  );

// pull command
program
  .command('pull')
  .description('Pull latest versions of tracked files from their remote origins')
  .argument('[ids...]', 'specific entry IDs to pull (default: all)')
  .option('--dry-run', 'show what would be pulled without making changes')
  .action(async (ids: string[], options: { dryRun?: boolean }) => {
    await pullCommand(ids, options);
  });

// status command
program
  .command('status')
  .description('Show which tracked files are current, outdated, or missing (offline)')
  .action(async () => {
    await statusCommand();
  });

// upgrade command
program
  .command('upgrade')
  .description('Upgrade dfiles to the latest published version')
  .action(async () => {
    await upgradeCommand();
  });

// list command
program
  .command('list')
  .description('List all tracked entries in the manifest')
  .option('--json', 'output as JSON')
  .action(async (options: { json?: boolean }) => {
    await listCommand(options);
  });

// remove command
program
  .command('remove')
  .description('Remove a tracked entry from the manifest by ID')
  .argument('<id>', 'entry ID to remove')
  .action(async (id: string) => {
    const { dir, manifest } = requireManifest();
    const entryIndex = manifest.entries.findIndex((entry) => entry.id === id);

    if (entryIndex === -1) {
      console.error(`Entry not found: ${id}`);
      process.exit(1);
    }

    manifest.entries.splice(entryIndex, 1);
    saveManifest(dir, manifest);
    console.log(`Removed entry '${id}'`);
  });

// Wrap execution to handle top-level async errors nicely
(async () => {
  try {
    await program.parseAsync(process.argv);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    console.error(`Error: ${message}`);
    process.exit(1);
  }
})();

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import type { Manifest } from './types';

export const MANIFEST_FILENAME = 'dfiles.json';

/**
 * Replaces leading ~ with os.homedir(), then path.resolve().
 * This is the single cross-platform path normalizer used everywhere.
 */
export function resolvePath(p: string): string {
  const expandedPath =
    p === '~'
      ? os.homedir()
      : p.startsWith('~/') || p.startsWith('~\\')
        ? path.join(os.homedir(), p.slice(2))
        : p;

  return path.resolve(expandedPath);
}

/**
 * Walks up from process.cwd() checking for dfiles.json at each level.
 * Returns the directory path that contains dfiles.json, or null if not found.
 * Stops at filesystem root.
 */
export function findManifestDir(): string | null {
  let current = process.cwd();

  while (true) {
    const manifestPath = path.join(current, MANIFEST_FILENAME);
    if (fs.existsSync(manifestPath)) {
      try {
        if (fs.statSync(manifestPath).isFile()) {
          return current;
        }
      } catch {
        // Ignore filesystem race conditions and continue walking upward.
      }
    }

    const parent = path.dirname(current);
    if (current === parent) {
      return null;
    }

    current = parent;
  }
}

function isManifest(value: unknown): value is Manifest {
  if (!value || typeof value !== 'object') {
    return false;
  }

  const maybeManifest = value as { version?: unknown; entries?: unknown };
  if (maybeManifest.version !== 1 || !Array.isArray(maybeManifest.entries)) {
    return false;
  }

  return maybeManifest.entries.every((entry) => {
    if (!entry || typeof entry !== 'object') {
      return false;
    }

    const candidate = entry as { [key: string]: unknown };
    return (
      typeof candidate.id === 'string' &&
      typeof candidate.repo === 'string' &&
      typeof candidate.branch === 'string' &&
      typeof candidate.source === 'string' &&
      typeof candidate.destination === 'string'
    );
  });
}

/**
 * Reads and JSON-parses dfiles.json from `dir`.
 * Throws a descriptive error if not found or malformed.
 */
export function loadManifest(dir: string): Manifest {
  const manifestPath = path.join(dir, MANIFEST_FILENAME);

  if (!fs.existsSync(manifestPath)) {
    throw new Error(
      `Manifest file not found at "${manifestPath}". Run "dfiles init" in your project root first.`,
    );
  }

  let parsed: unknown;
  try {
    const raw = fs.readFileSync(manifestPath, 'utf8');
    parsed = JSON.parse(raw);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Failed to read or parse manifest at "${manifestPath}": ${message}`);
  }

  if (!isManifest(parsed)) {
    throw new Error(
      `Manifest at "${manifestPath}" is malformed. Expected shape: { "version": 1, "entries": ManifestEntry[] }.`,
    );
  }

  return parsed;
}

/**
 * Writes JSON.stringify(manifest, null, 2) to dfiles.json in `dir`.
 */
export function saveManifest(dir: string, manifest: Manifest): void {
  const manifestPath = path.join(dir, MANIFEST_FILENAME);
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2), 'utf8');
}

/**
 * Calls findManifestDir(), throws actionable error if null.
 * Used by all commands except `init`.
 */
export function requireManifest(): { dir: string; manifest: Manifest } {
  const dir = findManifestDir();
  if (!dir) {
    throw new Error(
      `No ${MANIFEST_FILENAME} found in this directory or any parent directory. Run "dfiles init" in your project root first.`,
    );
  }

  return {
    dir,
    manifest: loadManifest(dir),
  };
}

